{
  "aggregate_id": "DEF-NRS-484A-135::motorcycle",
  "classifications": [
    {
      "class": "ru.bicycle",
      "verdict": "supported",
      "reason": "The contract describes a human-powered device, which the vehicle definition excepts and therefore cannot satisfy the motorcycle definition's motor-vehicle requirement."
    },
    {
      "class": "ru.bus",
      "verdict": "supported",
      "reason": "The passenger-carrying motor-vehicle contract does not determine whether the vehicle meets the three-wheel limit."
    },
    {
      "class": "ru.child",
      "verdict": "supported",
      "reason": "The contract describes a pedestrian person rather than a device qualifying as a motor vehicle."
    },
    {
      "class": "ru.commercial_motor_vehicle",
      "verdict": "supported",
      "reason": "Commercial mass or licensing does not establish or rule out the required motor-vehicle form, driver's seat or saddle, and wheel limit."
    },
    {
      "class": "ru.electric_bicycle",
      "verdict": "supported",
      "reason": "The motorcycle definition expressly excludes electric bicycles."
    },
    {
      "class": "ru.electric_scooter",
      "verdict": "supported",
      "reason": "Electric scooters are expressly excluded from motor vehicle, which is a prerequisite for motorcycle."
    },
    {
      "class": "ru.emergency_vehicle",
      "verdict": "supported",
      "reason": "Emergency designation does not determine whether a vehicle satisfies the motorcycle definition's physical requirements."
    },
    {
      "class": "ru.fire_apparatus",
      "verdict": "supported",
      "reason": "The fire-fighting-vehicle contract does not establish or rule out compliance with the three-wheel limit."
    },
    {
      "class": "ru.moped",
      "verdict": "supported",
      "reason": "The motorcycle definition expressly excludes mopeds."
    },
    {
      "class": "ru.motor_vehicle",
      "verdict": "supported",
      "reason": "The contract leaves seating and wheel count open, and an admitted seated three-wheeler need not be ridden astride or carry another qualifying class."
    },
    {
      "class": "ru.motorcycle",
      "verdict": "supported",
      "reason": "The contract's two- or three-wheeled motor vehicle ridden astride matches the admitting seat-or-saddle and wheel-limit language, and no exception removes that class."
    },
    {
      "class": "ru.official_vehicle",
      "verdict": "supported",
      "reason": "Official or contracted road service and identifying equipment do not determine the propulsion, seating, or wheel configuration required by the definition."
    },
    {
      "class": "ru.pedestrian",
      "verdict": "supported",
      "reason": "The contract describes a person rather than a motor vehicle, and the quoted exception also removes electric personal assistive mobility devices from vehicle."
    },
    {
      "class": "ru.pedestrian_with_white_cane_or_guide_animal",
      "verdict": "supported",
      "reason": "The contract describes a pedestrian person, not a device qualifying as a motor vehicle."
    },
    {
      "class": "ru.rail_vehicle",
      "verdict": "supported",
      "reason": "The motor-vehicle definition expressly requires that the vehicle not be operated upon rails."
    },
    {
      "class": "ru.school_bus",
      "verdict": "supported",
      "reason": "School designation and markings do not determine whether the bus meets the three-wheel limit."
    },
    {
      "class": "ru.taxicab",
      "verdict": "supported",
      "reason": "The marked passenger-for-hire contract does not determine propulsion or wheel count and therefore does not settle the motorcycle requirements."
    },
    {
      "class": "ru.tour_bus_or_limousine",
      "verdict": "supported",
      "reason": "The tour, shuttle, or lengthened-passenger-vehicle contract does not establish or rule out the required wheel configuration."
    },
    {
      "class": "ru.trailer_or_combination",
      "verdict": "supported",
      "reason": "The drawn-vehicle-or-combination contract does not settle whether the classified whole satisfies the motor-vehicle, driver's-seat, and wheel-limit requirements."
    },
    {
      "class": "ru.transit_bus",
      "verdict": "supported",
      "reason": "Public transit service and identifying displays do not determine whether the bus meets the three-wheel limit."
    },
    {
      "class": "ru.truck",
      "verdict": "supported",
      "reason": "A goods-carrying motor vehicle can meet the seating and three-wheel requirements, but its contract does not require them or require astride riding."
    }
  ]
}

